const COMMANDS: &[&str] = &["recognize"];

fn main() {
    // Generates permissions/autogenerated/** (allow-recognize / deny-recognize) and, when the
    // target is Android or iOS, exposes the native projects below to the app build.
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .ios_path("ios")
        .build();
}
